// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {BANK_SAFE} from "../src/BANK_SAFE.sol";

contract InvMutTest is Test {
    BANK_SAFE c;
    function setUp() public { c = new BANK_SAFE(); }

    function testFuzz_property(uint256 depositAmt, uint256 collectAmt) public {
        // wide admissible domain: 1..type(uint160).max deposits, collect at most the deposit
        depositAmt = bound(depositAmt, 1, type(uint160).max);
        collectAmt = bound(collectAmt, 1, depositAmt);

        // deploy a re-entrant callee that will re-enter Collect once from its receive()
        Attacker atk = new Attacker(c, collectAmt);

        // give the attacker enough value to deposit and set the reference's LogFile so external AddMessage calls do not revert
        vm.deal(address(atk), depositAmt);
        LogFile log = new LogFile();
        c.SetLogFile(address(log));
        c.Initialized();

        // attacker deposits, making balances[atk] = depositAmt and MinSum defaults to 0
        atk.deposit(depositAmt);

        // trigger the vulnerable flow: with one re-entrant Collect(msg.sender, collectAmt)
        atk.attack();

        // POSTCONDITION: the value actually observed by the attacker during its re-entrancy must be <= depositAmt - collectAmt
        // (the reference subtracts before the external call, so re-entrant observation is already decremented;
        //  the mutant subtracts after, so during the callback the attacker still sees the full balance and can withdraw twice).
        uint256 observedDuringCallback = atk.observedBalance();
        assertTrue(observedDuringCallback <= depositAmt - collectAmt, "reentrant observation not bounded by pre-decremented balance");
    }
}

contract Attacker {
    BANK_SAFE private c;
    uint256 private _collectAmt;
    uint256 public observedBalance;
    bool private _entered;

    constructor(BANK_SAFE _c, uint256 collectAmt_) {
        c = _c;
        _collectAmt = collectAmt_;
    }

    function deposit(uint256 value) external payable {
        c.Deposit{value: value}();
    }

    function attack() external {
        c.Collect(_collectAmt);
    }

    receive() external payable {
        if (!_entered) {
            _entered = true;
            observedBalance = c.balances(address(this));
            c.Collect(_collectAmt);
        }
    }
}

contract LogFile {
    struct Message {
        address Sender;
        string Data;
        uint Val;
        uint Time;
    }

    Message[] public History;
    Message LastMsg;

    function AddMessage(address _adr, uint _val, string memory _data) public {
        LastMsg.Sender = _adr;
        LastMsg.Time = block.timestamp;
        LastMsg.Val = _val;
        LastMsg.Data = _data;
        History.push(LastMsg);
    }
}
